  st('SUB-20260903-003.1','SUB-20260903-003','Easy mode was labelled "Story mode (not the intended experience)".','M','difficulty-modes',['D1'],'unknown','unstated','consistent');
  st('SUB-20260903-003.2','SUB-20260903-003','Players said the label made them feel they were playing a lesser version; some refused to use it while stuck.','E','difficulty-modes',['D1'],'mastery','failure','consistent');
  st('SUB-20260903-003.3','SUB-20260903-003','After renaming the mode, refund messages about difficulty went down.','E','difficulty-modes',['D1'],'unknown','success','consistent');
