function seedCourseBatch(S,n){const consents=['anonymous','named','internal','anonymous','optout','named','anonymous','internal','anonymous','optout','named','anonymous'];let stored=0,optout=0;
  for(let i=0;i<n;i++){const t=POOL[i%POOL.length];const c=consents[i%consents.length];if(c==='optout'){optout++;continue;}stored++;S.submissions.push({id:newSubId(S),source_type:'T1-course',channel:'course',contributor_role:'student',game:t.game,genre:t.genre,dev_phase:'Not stated',team_size:'Not stated',course_ref:'GAME-301, Fall 2026',consent:c,raw_text:(i>=POOL.length?'Second-round analysis. ':'')+t.text,received:TODAY(),status:'new',data_quality:'',is_valuable:true});}
  S.optOutLog.push({date:TODAY(),course_ref:'GAME-301, Fall 2026',received:n,stored,optout});return {stored,optout};}
