function cPublish(){
  const mds=UI.mdPreview?mech(UI.mdPreview):null;
  return `<h1>${t('Publish & log')}</h1><p class="muted">${t('In production a script reads the vault and writes')} <code>data.json</code> ${t('for the static site. Here the same data is generated from the simulation state — preview it, download it, and see what a mechanism page looks like as a vault Markdown file.')} ${t('The public site reads the same local data, so anything published here is live there immediately.')}</p>
  <div class="card flat"><div class="row"><button class="btn primary" data-action="gen-json">${t('Generate data.json preview')}</button><button class="btn" data-action="dl-json">${t('Download data.json')}</button><button class="btn" data-action="close-cycle">${t('Close this cycle')}</button><a class="btn" href="index.html" target="_blank">${t('Open public site')} ↗</a></div>${S.lastGenerated?`<p class="tiny muted" style="margin:8px 0 0">${t('Last generated')} ${S.lastGenerated}</p>`:''}${UI.jsonPreview?`<pre style="margin-top:10px">${esc(UI.jsonPreview)}</pre>`:''}</div>
  <div class="section"><h2>${t('Mechanism page as vault Markdown')}</h2><div class="row"><select data-action="md-preview" style="max-width:360px"><option value="">${t('— choose a mechanism —')}</option>${S.mechanisms.map(m=>`<option value="${m.id}" ${UI.mdPreview===m.id?'selected':''}>${esc(L(m,'name'))}</option>`).join('')}</select>${mds?`<button class="btn sm" data-action="dl-md" data-id="${mds.id}">${t('Download')} ${mds.id}.md</button>`:''}</div>${mds?`<pre style="margin-top:10px">${esc(mechanismMarkdown(mds))}</pre>`:''}</div>
  <div class="section"><h2>${t('Changelog')}</h2>${S.changelog.map(e=>`<p class="small"><code>${e.date}</code> ${esc(e.entry)}</p>`).join('')}</div>`;
}
function cThresholds(){
  const th=S.thresholds;const num=(k,label,step=0.05)=>`<div class="field"><label>${label} <code class="tiny">${k}</code></label><input type="number" step="${step}" name="${k}" value="${th[k]}"></div>`;
  return `<h1>${t('Thresholds')}</h1><p class="muted">${t('Every threshold the pipeline uses, in one place. Arbitrary defaults until calibrated; changes are logged.')} (design doc §16.3–16.5)</p>
  <form class="card" data-form="save-thresholds"><h3>${t('Source weights')}</h3><div class="grid cols-3">${Object.keys(th.source_weights).map(k=>`<div class="field"><label>${t(SOURCE_TYPES[k])}</label><input type="number" step="0.1" min="0" max="1" name="w:${k}" value="${th.source_weights[k]}"></div>`).join('')}</div>${num('course_cap','Course batch cap (share of W)')}
  <h3>S1</h3><div class="grid cols-3">${num('keep_sentence','Keep sentence if relevance ≥')}${num('flag_below','Flag if relevance <')}${num('field_conf_flag','Flag if field confidence <')}</div>
  <h3>${t('Evidence strength')}</h3><div class="grid cols-3">${num('strength_high_W','High: W ≥',0.5)}${num('strength_high_k','High: k ≥',1)}${num('strength_medium_W','Medium: W ≥',0.5)}</div>
  <h3>S3</h3><div class="grid cols-3">${num('obs_auto','Auto-log observation if relevance ≥')}${num('obs_review','Review observation if relevance ≥')}${num('graduate_W','Graduate: S ≥ θg',0.5)}${num('contradiction_ratio','Contradiction ratio K/S ≤')}${num('graduate_k','Graduate: k ≥',1)}</div>
  <h3>S4 ${t('Triggers worth checking')}</h3><div class="grid cols-3">${num('trigger_P_W','Principle: cluster W ≥',0.5)}${num('trigger_P_success','Principle: success share ≥')}${num('trigger_W_W','Pitfall: cluster W ≥',0.5)}${num('trigger_W_failure','Pitfall: failure share ≥')}${num('trigger_D1_sources','Pitfall: D1 sources ≥',1)}${num('trigger_F_high','Framework: high side ≥')}${num('trigger_F_low','Framework: low side ≤')}${num('trigger_F_side_W','Framework: each side W ≥',0.5)}</div>
  <h3>${t('Calibration rule')}</h3><p class="small muted">${t('automate a step when its agreement rate stays ≥')} ${Math.round(th.automate_agree*100)}% ${t('for')} ${th.calibration_cycles} ${t('cycles; tighten when it falls below')} ${Math.round(th.tighten_agree*100)}%.</p><div class="grid cols-3">${num('automate_agree','Automate when agreement ≥')}${num('tighten_agree','Tighten when agreement <')}${num('calibration_cycles','Consecutive cycles',1)}</div>
  <div class="row"><button class="btn primary" type="submit">${t('Save thresholds')}</button><button class="btn" type="button" data-action="reset-thresholds">${t('Reset defaults')}</button></div></form>
  <div class="section"><h2>${t('Agreement by step')}</h2>${agreementTable()}</div>`;
}
function cSim(){
  return `<h1>${t('Simulation controls')}</h1><p class="muted">${t('Everything here is local to this browser. Reset returns to the seeded demo state.')}</p>
  <div class="grid cols-2"><div class="card flat stack"><h3>${t('Feed the inbox')}</h3><button class="btn" data-action="seed-individual">${t('+ 3 individual submissions')}</button><button class="btn" data-action="seed-course">${t('+ Course batch of 12 (2 opt out)')}</button><p class="small muted">${t('Course batches show the consent tiers in action: opt-outs are counted, never stored.')}</p></div>
  <div class="card flat stack"><h3>${t('Run the pipeline')}</h3><button class="btn" data-action="draft-all">${t('S1 · Draft all new (simulated Claude)')}</button><button class="btn primary" data-action="gen-packet">${t('Generate packet (simulated pipeline)')}</button><p class="small muted">${t('The packet is what production Claude would hand you: every proposal from S1 to S4, for you to accept, edit or reject.')}</p></div>
  <div class="card flat stack"><h3>${t('State')}</h3><div class="row"><button class="btn" data-action="export-state">${t('Export state (.json)')}</button><label class="btn">${t('Import state')} <input type="file" accept="application/json" class="sr" data-action="import-state"></label></div><button class="btn danger" data-action="reset">${t('Reset to seed')}</button></div>
  <div class="card flat"><h3>${t('What is simulated')}</h3><ul class="small"><li><strong>Claude S1</strong> → keyword heuristics (EN + 中文). Production: the coding prompt; you still review flagged lines.</li><li><strong>Forms → Sheet → inbox</strong> → the Contribute page writes straight into the inbox.</li><li><strong>Review packet</strong> → generated here; production Claude writes <code>cycle-*.json</code>, you return <code>decisions.json</code>.</li><li><strong>data.json / vault Markdown</strong> → generated in the browser, downloadable.</li></ul></div></div>`;
}
/* ---------- actions ---------- */
Object.assign(ZH,{'Clustering is done by the pipeline: it groups reviewed statements and writes a first pattern sentence. Your job is only to accept or rewrite those sentences in the review packet. This page shows what has been saved, and lets you explore other groupings if you are curious.':'聚类由流水线完成：它把已审陈述分组并写出第一版模式句。你只需要在审核包里接受或改写那句话。这一页显示已保存的聚类，好奇的话也可以按别的轴探索。','proposed clusters are waiting in the':'个提议的聚类正在','Explore other groupings':'探索其他分组','show statements':'显示陈述','The packet is what production Claude would hand you: every proposal from S1 to S4, for you to accept, edit or reject.':'审核包就是正式版 Claude 交给你的东西：S1 到 S4 的每一条提议，供你接受、修改或拒绝。','Step':'步骤','Accepted':'已接受','Rate':'比例','Packet generated':'审核包已生成','Decisions exported':'决定已导出','Packet imported':'审核包已导入','Not a packet file':'不是审核包文件','Idea captured':'碎片已记下','Mechanism saved':'机制已保存','Case saved':'案例已保存','Post saved':'文章已保存','Thresholds saved':'阈值已保存','Thresholds reset':'阈值已恢复默认','No open packet':'没有打开的审核包'});
function approveSubmission(id){const s=sub(id);if(!s)return;S.statements.filter(x=>x.submission_id===id).forEach(x=>{x.review_status='reviewed';x.review_flag=false;});s.status='reviewed';if(!s.data_quality)s.data_quality='medium';}
function listIds(v){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean);}
document.addEventListener('click',e=>{
  const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
  if(a==='lang'){setLang(el.dataset.lang);return;}
  if(a==='reset'){try{localStorage.removeItem(STORE_KEY);}catch(x){}S=seedState();save();UI.jsonPreview=null;UI.mdPreview='';toast(t('Reset to seed'));render();return;}
  if(a==='seed-individual'){seedIndividual(S,3);save();toast('3 '+t('submissions added'));render();return;}
  if(a==='seed-course'){const r=seedCourseBatch(S,12);save();toast(`${t('Course batch:')} ${r.stored} ${t('stored,')} ${r.optout} ${t('opted out (nothing stored)')}`);render();return;}
  if(a==='draft-all'){let n=0;S.submissions.filter(s=>s.status==='new').forEach(s=>{draftStatements(S,s);n++;});save();toast(`${t('Drafted')} ${n}`);render();return;}
  if(a==='draft-one'){draftStatements(S,sub(el.dataset.sub));save();toast(t('Drafted'));render();return;}
  if(a==='add-stmt'){const s=sub(el.dataset.sub);const n=S.statements.filter(x=>x.submission_id===s.id).length+1;S.statements.push({id:s.id+'.'+n,submission_id:s.id,text:'',lang:hasCJK(s.raw_text)?'zh':'en',layer:'M',mechanism:'',dimensions:[],stance:'unknown',outcome:'unstated',alignment:'consistent',needs_context:false,review_flag:false,review_status:'draft',framework_version:S.frameworkVersion});if(s.status==='new')s.status='drafted';save();render();return;}
  if(a==='del-stmt'){S.statements=S.statements.filter(x=>x.id!==el.dataset.stmt);save();render();return;}
  if(a==='approve-sub'){approveSubmission(el.dataset.sub);save();toast(t('Marked reviewed'));nav('#/coding');return;}
  if(a==='toggle-group'){UI.openGroup=UI.openGroup===el.dataset.key?null:el.dataset.key;render();return;}
  if(a==='open-form'){UI.openForm=UI.openForm===el.dataset.form?null:el.dataset.form;render();return;}
  if(a==='publish'||a==='unpublish'){const o=byId(S.outputs,el.dataset.id);o.status=a==='publish'?'published':'draft';logChange((a==='publish'?'Published ':'Unpublished ')+o.id+' — '+o.title);save();toast(t(o.status==='published'?'Published — visible on the public site':'Unpublished'));render();return;}
  if(a==='del-output'){S.outputs=S.outputs.filter(o=>o.id!==el.dataset.id);save();nav('#/outputs');return;}
  if(a==='gen-json'){UI.jsonPreview=JSON.stringify(buildPublicData(),null,2);S.lastGenerated=new Date().toLocaleString();save();render();return;}
  if(a==='dl-json'){download('data.json',JSON.stringify(buildPublicData(),null,2));return;}
  if(a==='dl-md'){const m=mech(el.dataset.id);download(m.id+'.md',mechanismMarkdown(m),'text/markdown');return;}
  if(a==='close-cycle'){const c=counts();S.cycles.unshift({date:TODAY(),subs:S.submissions.filter(s=>s.status==='reviewed').length,stmts:c.reviewedStmts,clusters:S.clusters.length,obs:S.observations.length,grads:S.claims.filter(x=>x.status!=='observing').length,published:c.published});if(S.packets[0])S.packets[0].status='closed';logChange('Cycle closed.');save();toast(t('Cycle closed'));render();return;}
  if(a==='export-state'){download('ddv-sim-state.json',JSON.stringify(S,null,2));return;}
  if(a==='gen-packet'){const pk=buildPacket();save();toast(`${t('Packet generated')}: ${pk.items.length} ${t('items')}`);nav('#/packet');render();return;}
  if(a==='dl-packet'){const pk=S.packets[0];if(pk)download(pk.id+'.json',JSON.stringify(pk,null,2));return;}
  if(a==='export-decisions'){const pk=S.packets[0];if(!pk){toast(t('No open packet'));return;}download('decisions-'+pk.id+'.json',JSON.stringify({packet:pk.id,decided:new Date().toISOString(),decisions:pk.items.map(i=>({item:i.id,step:i.step,ref:i.ref,decision:i.decision,edited:i.edited||null}))},null,2));toast(t('Decisions exported'));return;}
  if(a==='pk-accept-unflagged'){const pk=S.packets[0];if(!pk)return;let n=0;pk.items.filter(i=>!i.decision).forEach(i=>{const flagged=i.step==='S1'&&S.statements.some(x=>x.submission_id===i.ref&&x.review_flag);if(!flagged&&i.step!=='S3-grad'){applyDecision(pk,i,'accept');n++;}});if(pk.items.every(i=>i.decision))pk.status='decided';save();toast(`${t('Accepted')} ${n}`);render();return;}
  if(a==='pk-toggle'){const id=el.dataset.item;UI.pkOpen.has(id)?UI.pkOpen.delete(id):UI.pkOpen.add(id);render();return;}
  if(a==='del-cluster'){S.clusters=S.clusters.filter(c=>c.id!==el.dataset.id);save();render();return;}
  if(a==='del-stmt-pk'){S.statements=S.statements.filter(x=>x.id!==el.dataset.stmt);save();render();return;}
  if(a==='pk-decide'){const pk=S.packets[0];const item=pk.items.find(i=>i.id===el.dataset.item);if(item&&!item.decision){applyDecision(pk,item,el.dataset.d);if(pk.items.every(i=>i.decision))pk.status='decided';save();render();}return;}
  if(a==='idea-from'){S.counters.idea++;S.postIdeas.unshift({id:'IDEA-'+String(S.counters.idea).padStart(3,'0'),date:TODAY(),text:el.dataset.text,source:route().join('/')});save();toast(t('Idea captured'));return;}
  if(a==='idea-to-post'){const i=byId(S.postIdeas,el.dataset.id);UI.draftPost={id:'',title:i.text.slice(0,70),title_zh:'',body:i.text+'\n\n',body_zh:'',refs:[],status:'draft',date:TODAY()};S.postIdeas=S.postIdeas.filter(x=>x.id!==i.id);save();nav('#/posts/new');return;}
  if(a==='del-idea'){S.postIdeas=S.postIdeas.filter(x=>x.id!==el.dataset.id);save();render();return;}
  if(a==='reset-thresholds'){S.thresholds=JSON.parse(JSON.stringify(DEFAULT_THRESHOLDS));logChange('Thresholds reset to defaults.');save();toast(t('Thresholds reset'));render();return;}
  if(a==='advisor-pick'){UI.advisor.answers[el.dataset.key]=el.dataset.v;render();return;}
  if(a==='advisor-reset'){UI.advisor={answers:{}};render();return;}
});
document.addEventListener('change',e=>{
  const el=e.target;
  if(el.dataset.action==='cat'){UI.cat=el.value;render();return;}
  if(el.dataset.action==='packet-filter'){UI.packetFilter=el.value;render();return;}
  if(el.dataset.action==='set-axis'){UI.axis=el.value;UI.openGroup=null;render();return;}
  if(el.dataset.action==='md-preview'){UI.mdPreview=el.value;render();return;}
  if(el.dataset.action==='prefill-claim'){const c=byId(S.claims,el.value);if(!c)return;const ids=claimEvidenceIds(c);UI.draftOutput={id:'',type:'P',title:c.statement.split(':')[0].slice(0,70),title_zh:c.statement_zh?c.statement_zh.split('：')[0].slice(0,40):'',advice:c.statement,advice_zh:c.statement_zh||'',why:'Drafted from '+c.id+' ('+weightedSources(ids).n+' independent sources, W='+weightedSources(ids).W+'). Explain why this matters to a developer in two sentences.',why_zh:'',how:'Concrete steps a small team can take this week.',how_zh:'',evidence:ids,claims:[c.id],mechanisms:[...new Set(ids.map(i=>stmt(i)?.mechanism).filter(Boolean))],audience:'',audience_zh:'',status:'draft'};render();return;}
  if(el.dataset.action==='import-state'){const f=el.files[0];if(!f)return;f.text().then(x=>{try{const s=JSON.parse(x);if(s&&s.version===2){S=s;save();toast(t('State imported'));render();}else toast(t('Not a simulation state file'));}catch(err){toast(t('Invalid JSON'));}});return;}
  if(el.dataset.action==='import-packet'){const f=el.files[0];if(!f)return;f.text().then(x=>{try{const pk=JSON.parse(x);if(pk&&pk.items&&pk.id){pk.status='open';S.packets.unshift(pk);save();toast(t('Packet imported'));render();}else toast(t('Not a packet file'));}catch(err){toast(t('Invalid JSON'));}});return;}
  if(el.dataset.pkitem){const pk=S.packets[0];const it=pk&&pk.items.find(i=>i.id===el.dataset.pkitem);if(it&&!it.decision){it.proposal[el.dataset.pkfield]=el.value;it.edited=true;save();}return;}
  if(el.dataset.sub&&el.dataset.field){const s=sub(el.dataset.sub);if(!s)return;s[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;save();return;}
  if(el.dataset.stmt&&el.dataset.field){const st=stmt(el.dataset.stmt);if(!st)return;const f=el.dataset.field;if(f==='dimensions'){const set=new Set(st.dimensions);el.checked?set.add(el.value):set.delete(el.value);st.dimensions=[...set];}else if(el.type==='checkbox')st[f]=el.checked;else st[f]=el.value;if(f==='mechanism'||f==='layer'){st.review_flag=st.layer==='X'||!st.mechanism;render();}save();return;}
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.action==='search'){UI.search=el.value;render();const inp=document.querySelector('[data-action=search]');if(inp){inp.focus();inp.setSelectionRange(inp.value.length,inp.value.length);}return;}if(el.dataset.stmt&&el.dataset.field==='text'){const st=stmt(el.dataset.stmt);if(st){st.text=el.value;save();}}});
document.addEventListener('submit',e=>{
  const f=e.target;e.preventDefault();const fd=new FormData(f);const then=e.submitter?.value||'save';
  if(f.id==='contributeForm'){const consent=fd.get('consent');if(consent==='optout'){S.optOutLog.push({date:TODAY(),course_ref:fd.get('course_ref')||'(individual)',received:1,stored:0,optout:1});save();nav('#/contribute/declined');return;}const isCourse=!!(fd.get('course_ref')||'').trim();S.submissions.push({id:newSubId(S),source_type:isCourse?'T1-course':'T1-form',channel:isCourse?'course':'individual',contributor_role:fd.get('role'),game:fd.get('game')||'(unnamed)',genre:fd.get('genre')||'',dev_phase:fd.get('phase'),team_size:fd.get('team'),course_ref:fd.get('course_ref')||'',consent,raw_text:fd.get('text'),received:TODAY(),status:'new',data_quality:'',is_valuable:true});save();nav('#/contribute/thanks');return;}
  const kind=f.dataset.form;
  if(kind==='save-cluster'){const key=f.dataset.key;const ids=reviewedStatements().filter(st=>{const k=groupKey(st,UI.axis);return Array.isArray(k)?k.includes(key):k===key;}).map(st=>st.id);S.counters.cl++;S.clusters.push({id:'CL-'+TODAY().replace(/-/g,'')+'-'+String.fromCharCode(65+((S.counters.cl-1)%26)),name:fd.get('name'),axis:UI.axis,statement_ids:ids,pattern:fd.get('pattern'),confidence:fd.get('confidence'),created:TODAY()});UI.openGroup=null;save();toast(t('Cluster saved'));render();return;}
  if(kind==='new-claim'){S.counters.claim++;const id='C-'+String(S.counters.claim).padStart(3,'0');S.claims.push({id,statement:fd.get('statement'),origin:fd.get('origin'),scope:fd.get('scope'),status:'observing',evidence_for:fd.getAll('stmts'),evidence_against:[],graduation_note:'',history:[{date:TODAY(),note:'Created as observing from community evidence.'}]});logChange('New observing claim '+id+'.');UI.openForm=null;save();toast(id+' '+t('created'));render();return;}
  if(kind==='log-obs'){const ids=fd.getAll('stmts');if(!ids.length){toast(t('Pick at least one statement'));return;}S.counters.ob++;S.observations.push({id:'OB-'+String(S.counters.ob).padStart(3,'0'),date:TODAY(),claim_id:f.dataset.claim,statement_ids:ids,direction:fd.get('direction'),note:fd.get('note')});UI.openForm=null;save();toast(t('Observation logged'));render();return;}
  if(kind==='graduate'){const c=byId(S.claims,f.dataset.claim);const status=fd.get('status');const old=c.statement;c.status=status;if(status==='revised')c.statement=fd.get('statement');c.graduation_note=fd.get('note');c.history.push({date:TODAY(),note:`${status.toUpperCase()} — ${fd.get('note')}`+(status==='revised'&&old!==c.statement?` (was: "${old}")`:'')});bumpFramework();logChange(`Claim ${c.id} → ${status}: ${fd.get('note')} (framework v${S.frameworkVersion})`);UI.openForm=null;save();toast(`${c.id} ${t('is now')} ${t(status)} · ${t('framework v')}${S.frameworkVersion}`);render();return;}
  if(kind==='save-output'){let o=byId(S.outputs,f.dataset.id);const data={};['type','title','title_zh','advice','advice_zh','why','why_zh','how','how_zh','audience','audience_zh'].forEach(k=>data[k]=fd.get(k)||'');data.mechanisms=fd.getAll('mechanisms');data.claims=fd.getAll('claims');data.evidence=fd.getAll('evidence');
    if(!o){const tp=data.type;S.counters.out[tp]++;o={id:tp+'-'+String(S.counters.out[tp]).padStart(3,'0'),status:'draft',created:TODAY()};S.outputs.push(o);UI.draftOutput=null;}
    Object.assign(o,data);if(then==='publish'){o.status='published';logChange('Published '+o.id+' — '+o.title);}if(then==='unpublish'){o.status='draft';logChange('Unpublished '+o.id);}save();toast(t(then==='publish'?'Published — visible on the public site':'Saved'));nav('#/outputs');return;}
  if(kind==='save-mech'){let m=mech(f.dataset.id);const data={};['name','name_zh','category','subcategory','one_liner','one_liner_zh','when_to_use','when_to_use_zh'].forEach(k=>data[k]=fd.get(k)||'');data.fit={structure:fd.getAll('fit_structure'),feeling:fd.getAll('fit_feeling'),team:fd.getAll('fit_team')};data.strong_links=listIds(fd.get('strong_links'));data.weak_links=listIds(fd.get('weak_links'));
    if(!m){const id=(fd.get('id')||'').toLowerCase().replace(/[^a-z0-9-]+/g,'-');if(!id||mech(id)){toast('ID missing or taken');return;}m={id,tensions:[]};S.mechanisms.push(m);logChange('New mechanism '+id+'.');}
    Object.assign(m,data);save();toast(t('Mechanism saved'));nav('#/library/'+m.id);return;}
  if(kind==='save-case'){const mid=f.dataset.mech;const id='CASE-'+(fd.get('game')||'x').toLowerCase().replace(/[^a-z0-9]+/g,'')+'-'+mid;S.cases.push({id,game:fd.get('game'),mechanism:mid,description:fd.get('description'),description_zh:fd.get('description_zh')||'',source:fd.get('source')||'curator',worked:fd.get('worked')});save();toast(t('Case saved'));render();return;}
  if(kind==='save-post'){let p=byId(S.posts,f.dataset.id);const data={title:fd.get('title'),title_zh:fd.get('title_zh')||'',body:fd.get('body'),body_zh:fd.get('body_zh')||'',refs:listIds(fd.get('refs'))};if(!p){S.counters.post++;p={id:'POST-'+String(S.counters.post).padStart(3,'0'),status:'draft',date:TODAY()};S.posts.unshift(p);UI.draftPost=null;}Object.assign(p,data);if(then==='publish'){p.status='published';p.date=TODAY();logChange('Published post '+p.id+' — '+p.title);}if(then==='unpublish')p.status='draft';save();toast(t(then==='publish'?'Published — visible on the public site':'Post saved'));nav('#/posts');return;}
  if(kind==='add-idea'){S.counters.idea++;S.postIdeas.unshift({id:'IDEA-'+String(S.counters.idea).padStart(3,'0'),date:TODAY(),text:fd.get('text'),source:''});save();toast(t('Idea captured'));render();return;}
  if(kind==='save-thresholds'){const th=S.thresholds;for(const [k,v] of fd.entries()){if(k.startsWith('w:'))th.source_weights[k.slice(2)]=parseFloat(v);else if(k in th)th[k]=parseFloat(v);}logChange('Thresholds updated.');save();toast(t('Thresholds saved'));render();return;}
});
window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#/advisor'))UI.advisor={answers:{}};if(!location.hash.startsWith('#/outputs/new'))UI.draftOutput=null;if(!location.hash.startsWith('#/posts/new'))UI.draftPost=null;UI.openForm=null;UI.openGroup=null;render();});
window.addEventListener('storage',e=>{if(e.key===STORE_KEY){S=load();render();}});
document.documentElement.lang=LANG==='zh'?'zh-CN':'en';
render();
